-- 鲜蔬源：system模块最终结构与默认数据（截至原V244）。
-- 仅用于空库初始化；已有库先通过显式基线切换工具核对并接管。
CREATE SCHEMA IF NOT EXISTS xsy_v2;
SET search_path TO xsy_v2, public;
SET check_function_bodies = false;

CREATE SEQUENCE xsy_v2.t_file_relation_relation_id_seq
  START WITH 1
  INCREMENT BY 1
  NO MINVALUE
  NO MAXVALUE
  CACHE 1;

CREATE TABLE xsy_v2.t_change_log (
  change_log_id bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY (SEQUENCE NAME xsy_v2.t_change_log_change_log_id_seq
                                                                  START WITH 1
                                                                  INCREMENT BY 1
                                                                  NO MINVALUE
                                                                  NO MAXVALUE
                                                                  CACHE 1),
  update_version varchar(255) NOT NULL,
  type integer NOT NULL,
  publish_author varchar(255) NOT NULL,
  public_date date NOT NULL,
  content text NOT NULL,
  link text,
  create_time timestamp DEFAULT CURRENT_TIMESTAMP NOT NULL,
  update_time timestamp DEFAULT CURRENT_TIMESTAMP NOT NULL,
  CONSTRAINT pk_t_change_log PRIMARY KEY (change_log_id),
  CONSTRAINT uk_t_change_log_version_unique UNIQUE (update_version)
);

COMMENT ON TABLE xsy_v2.t_change_log
  IS 't_change_log';

COMMENT ON COLUMN xsy_v2.t_change_log.change_log_id
  IS '更新日志id';

COMMENT ON COLUMN xsy_v2.t_change_log.update_version
  IS '版本';

COMMENT ON COLUMN xsy_v2.t_change_log.type
  IS '更新类型:[1:特大版本功能更新;2:功能更新;3:bug修复]';

COMMENT ON COLUMN xsy_v2.t_change_log.publish_author
  IS '发布人';

COMMENT ON COLUMN xsy_v2.t_change_log.public_date
  IS '发布日期';

COMMENT ON COLUMN xsy_v2.t_change_log.content
  IS '更新内容';

COMMENT ON COLUMN xsy_v2.t_change_log.link
  IS '跳转链接';

COMMENT ON COLUMN xsy_v2.t_change_log.create_time
  IS '创建时间';

COMMENT ON COLUMN xsy_v2.t_change_log.update_time
  IS '更新时间';

