  IS '创建时间';

CREATE TABLE xsy_v2.t_data_tracer (
  data_tracer_id bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY (SEQUENCE NAME xsy_v2.t_data_tracer_data_tracer_id_seq
                                                                   START WITH 1
                                                                   INCREMENT BY 1
                                                                   NO MINVALUE
                                                                   NO MAXVALUE
                                                                   CACHE 1),
  data_id bigint NOT NULL,
  type integer NOT NULL,
  content text,
  diff_old text,
  diff_new text,
  extra_data text,
  user_id bigint NOT NULL,
  user_type integer NOT NULL,
  user_name varchar(50) NOT NULL,
  ip varchar(50) DEFAULT CAST(NULL AS varchar),
  ip_region varchar(1000) DEFAULT CAST(NULL AS varchar),
  user_agent varchar(2000) DEFAULT CAST(NULL AS varchar),
  update_time timestamp DEFAULT CURRENT_TIMESTAMP NOT NULL,
  create_time timestamp DEFAULT CURRENT_TIMESTAMP NOT NULL,
  CONSTRAINT pk_t_data_tracer PRIMARY KEY (data_tracer_id)
);

