COMMENT ON COLUMN xsy_v2.t_data_tracer.user_name
  IS '用户名称';

COMMENT ON COLUMN xsy_v2.t_data_tracer.ip
  IS 'ip';

COMMENT ON COLUMN xsy_v2.t_data_tracer.ip_region
  IS 'ip地区';

COMMENT ON COLUMN xsy_v2.t_data_tracer.user_agent
  IS '用户ua';

COMMENT ON COLUMN xsy_v2.t_data_tracer.update_time
  IS '更新时间';

COMMENT ON COLUMN xsy_v2.t_data_tracer.create_time
  IS '创建时间';

