CREATE TABLE xsy_v2.t_file (
  file_id bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY (SEQUENCE NAME xsy_v2.t_file_file_id_seq
                                                            START WITH 1
                                                            INCREMENT BY 1
