  file_key varchar(200) NOT NULL,
  file_type varchar(50) NOT NULL,
  creator_id bigint,
  creator_user_type integer,
  creator_name varchar(100) DEFAULT CAST(NULL AS varchar),
  update_time timestamp DEFAULT CURRENT_TIMESTAMP,
  create_time timestamp DEFAULT CURRENT_TIMESTAMP NOT NULL,
  CONSTRAINT pk_t_file PRIMARY KEY (file_id),
  CONSTRAINT uk_t_file_uk_file_key UNIQUE (file_key)
);

COMMENT ON TABLE xsy_v2.t_file
  IS 't_file';

COMMENT ON COLUMN xsy_v2.t_file.file_id
  IS '主键ID';

COMMENT ON COLUMN xsy_v2.t_file.folder_type
  IS '文件夹类型';

COMMENT ON COLUMN xsy_v2.t_file.file_name
  IS '文件名称';

COMMENT ON COLUMN xsy_v2.t_file.file_size
  IS '文件大小';

COMMENT ON COLUMN xsy_v2.t_file.file_key
  IS '文件key，用于文件下载';

COMMENT ON COLUMN xsy_v2.t_file.file_type
  IS '文件类型';

