  IS '上次更新时间';

COMMENT ON COLUMN xsy_v2.t_file.create_time
  IS '创建时间';

CREATE TABLE xsy_v2.t_file_relation (
  relation_id bigint NOT NULL DEFAULT nextval(CAST('xsy_v2.t_file_relation_relation_id_seq' AS regclass)),
  file_key varchar(200) NOT NULL,
  biz_type varchar(50) NOT NULL,
  biz_id bigint NOT NULL,
  create_time timestamp DEFAULT CURRENT_TIMESTAMP NOT NULL,
  update_time timestamp DEFAULT CURRENT_TIMESTAMP NOT NULL,
  deleted_flag boolean DEFAULT FALSE NOT NULL,
  CONSTRAINT ck_t_file_relation_biz_type CHECK (((biz_type)::text = ANY ((ARRAY['ENTERPRISE'::character varying, 'NOTICE'::character varying, 'HELP_DOC'::character varying, 'FEEDBACK'::character varying, 'PRODUCT'::character varying, 'PRODUCT_QUALIFICATION'::character varying, 'LOT_INSPECTION'::character varying, 'TRACE_INSPECTION_REPORT'::character varying])::text[]))),
  CONSTRAINT ck_t_file_relation_key_not_blank CHECK (length(btrim(CAST(file_key AS text))) > 0),
  CONSTRAINT t_file_relation_pkey PRIMARY KEY (relation_id)
);

COMMENT ON TABLE xsy_v2.t_file_relation
  IS '业务对象与文件附件的授权关系（有权看对象即可看其文件）';

COMMENT ON COLUMN xsy_v2.t_file_relation.relation_id
  IS '主键 ID';

COMMENT ON COLUMN xsy_v2.t_file_relation.file_key
  IS 't_file.file_key 的值，不建外键';

COMMENT ON COLUMN xsy_v2.t_file_relation.biz_type
  IS '业务对象类型：ENTERPRISE / NOTICE / HELP_DOC / FEEDBACK / PRODUCT / PRODUCT_QUALIFICATION / LOT_INSPECTION / TRACE_INSPECTION_REPORT';

COMMENT ON COLUMN xsy_v2.t_file_relation.biz_id
  IS '该业务类型下的对象主键';

COMMENT ON COLUMN xsy_v2.t_file_relation.create_time
  IS '创建时间';

COMMENT ON COLUMN xsy_v2.t_file_relation.update_time
  IS '更新时间';

COMMENT ON COLUMN xsy_v2.t_file_relation.deleted_flag
  IS '软删除；业务对象删除时同步置位，物理文件不删';

ALTER SEQUENCE xsy_v2.t_file_relation_relation_id_seq OWNED BY xsy_v2.t_file_relation.relation_id;

