                                                                    START WITH 1
                                                                    INCREMENT BY 1
                                                                    NO MINVALUE
                                                                    NO MAXVALUE
                                                                    CACHE 1),
  user_id bigint NOT NULL,
  user_type integer NOT NULL,
  table_id integer NOT NULL,
  columns text,
  create_time timestamp DEFAULT CURRENT_TIMESTAMP NOT NULL,
  update_time timestamp DEFAULT CURRENT_TIMESTAMP NOT NULL,
  CONSTRAINT pk_t_table_column PRIMARY KEY (table_column_id),
  CONSTRAINT uk_t_table_column_uni_employee_table UNIQUE (user_id, table_id)
);

COMMENT ON TABLE xsy_v2.t_table_column
  IS 't_table_column';

COMMENT ON COLUMN xsy_v2.t_table_column.table_column_id
  IS '主键ID';

COMMENT ON COLUMN xsy_v2.t_table_column.user_id
  IS '用户id';

COMMENT ON COLUMN xsy_v2.t_table_column.user_type
  IS '用户类型';

COMMENT ON COLUMN xsy_v2.t_table_column.table_id
  IS '表格id';

COMMENT ON COLUMN xsy_v2.t_table_column.columns
  IS '具体的表格列，存入的json';

COMMENT ON COLUMN xsy_v2.t_table_column.create_time
  IS '创建时间';

COMMENT ON COLUMN xsy_v2.t_table_column.update_time
  IS '更新时间';

