INSERT INTO xsy_v2.t_help_doc (help_doc_id,
                               help_doc_catalog_id,
                               title,
                               content_text,
                               content_html,
                               attachment,
                               sort,
                               page_view_count,
                               user_view_count,
                               author,
                               update_time,
                               create_time)
VALUES (18,
        4,
        '一物一码：发码与追溯',
        '入口：库存 → 包装码。先按批次发码，再绑定到分拣行，扫码可查商品、批次与去向；已绑定的码不能作废。',
        '<p>入口：库存 → 包装码。</p><ol><li>发码：选批次与包装类型，生成一批码并打印标签。</li><li>绑定：分拣时把码绑定到分拣行，绑定即承诺给某个客户。</li><li>追溯：扫码查商品、来源批次、绑定客户与订单。</li><li>作废：未绑定的码可作废；已绑定的码不能作废，只能走更正流程。</li><li>打印：包装码标签用 80mm 热敏纸，票面不含价格。</li></ol><p>常见卡点：码不透明且永不复用，不要手工改码；作废只是标记状态，不删除绑定记录。</p>',
        NULL,
        21,
        0,
        0,
        'system',
        CURRENT_TIMESTAMP,
        CURRENT_TIMESTAMP),
       (9,
        4,
        '营销活动与首页装修',
        '入口：营销 → 活动、优惠券；商城 → 首页装修。活动设时间与商品范围；首页装修用草稿编辑、预览、发布、恢复四步，主题只换配色不换版式，主题随发布版本一起恢复。',
        '<p>入口：营销 → 活动 / 优惠券；商城 → 首页装修。</p><ol><li>建活动：选类型、设起止时间、指定商品范围与优惠力度。</li><li>发券：在领券中心配置可领数量与有效期。</li><li>装修首页：选主题（生鲜绿/暖橙/海蓝）→ 加组件并排序 → 预览 → 发布。</li><li>恢复：首页装修 → 发布历史，选目标版本恢复，配色随版本一起回去。</li></ol><p>常见卡点：草稿有未保存修改时不能发布；组件为空时发布会被拒绝。</p>',
        NULL,
        12,
        0,
        0,
        'system',
        CURRENT_TIMESTAMP,
        CURRENT_TIMESTAMP),
       (12,
        4,
        '库存：盘点、损溢、调拨与转换',
        '入口：库存 → 盘点 / 损溢 / 调拨 / 规格转换。盘点先建单再录入实盘数，差异走审批；损溢与转换都要审批后生效；库存流水只追加，不能修改或删除。',
        '<p>入口：库存 → 盘点 / 损溢 / 调拨 / 规格转换。</p><ol><li>盘点：新建盘点单 → 录入实盘数 → 提交 → 审批，差异生成损溢记录。</li><li>损溢：新建报损/报溢单，填原因与数量，审批后改库存。</li><li>调拨：选调出仓与调入仓，提交后由调入方确认。</li><li>规格转换：整件拆零或反向合并，审批后生成两条反向流水。</li><li>预警：库存预警按阈值触发，可在列表查看待处理项。</li></ol><p>常见卡点：流水是追加记录，发现问题用反向单据更正，不要试图删改历史流水。</p>',
        NULL,
        15,
        0,
        0,
        'system',
        CURRENT_TIMESTAMP,
        CURRENT_TIMESTAMP),
       (7,
        4,
        '商品建档与改价',
        '入口：商品 → 商品档案。新建商品先填商品名、分类、类型（标品/非标品），再逐个加商品规格并填销售单位、市场价。批量改分类与图片用列表上方的批量操作。商品与供应商的对应关系在「商品供应商」里维护，一个规格可以挂多个供应商。',
        '<p>入口：商品 → 商品档案。</p><ol><li>新建商品：填商品名、分类、类型，保存后进入规格。</li><li>加规格：填规格名、销售单位、市场价；非标品还要填称重单位。</li><li>改价：规格行内直接改市场价；协议价与客户类型价在「定价」菜单，不在这里。</li><li>批量操作：勾选多行后批量改分类、批量传图。</li><li>供应商关系：商品 → 商品供应商，一个规格可挂多个供应商并设采购单位。</li></ol><p>常见卡点：规格已下架时不能改价；商品与规格状态是两件事，商品下架不影响规格单独在售。</p>',
        NULL,
        10,
        0,
        0,
        'system',
        CURRENT_TIMESTAMP,
        CURRENT_TIMESTAMP),
       (16,
        4,
        '后台：权限、模板与日志',
        '入口：系统 → 角色/员工/菜单；打印 → 单据模板；系统 → 操作日志。权限按角色授予，菜单与操作权限一一对应；单据模板改版式不改字段白名单。',
        '<p>入口：系统 → 角色 / 员工 / 菜单；打印 → 单据模板；系统 → 操作日志。</p><ol><li>配权限：角色里勾选菜单，保存后对应账号重新登录生效。</li><li>数据范围：客户、采购、仓库各有本人与全部两类查询权限，两者相交不相互替代。</li><li>单据模板：改抬头与列，字段只能从白名单里选。</li><li>查日志：按操作人、时间、业务对象筛选；日志页可带业务上下文下钻。</li><li>帮助：本页即帮助中心，按模块查操作步骤。</li></ol><p>常见卡点：没有对应菜单权限时系统会直接拒绝；数据范围为空等于看不到任何数据。</p>',
        NULL,
        19,
        0,
        0,
        'system',
        CURRENT_TIMESTAMP,
        CURRENT_TIMESTAMP),
       (14,
        4,
        '配送：排线、发车与签收',
        '入口：配送 → 配送线路。先建线路并选停靠点，再按区域、时间、数量与金额看建议；发车原子生成销售出库，签收只记录结果不撤销出库。',
        '<p>入口：配送 → 配送线路。</p><ol><li>建线路：选司机、车辆、停靠点顺序；顺序由人确认，系统不自动应用建议。</li><li>排线：看候选订单与地图分布，把订单挂到线路上。</li><li>发车：整条线路一次提交，任一订单不合格整条拒绝；发车即产生销售出库。</li><li>签收：按订单记录「已签收」或带原因的「异常」，签收不撤销出库。</li><li>打印：线路发货单、按订单、按客户三种模板。</li></ol><p>常见卡点：线路未排完不能发车；签收异常需填原因，异常会进入异常工作台。</p>',
        NULL,
        17,
        0,
        0,
        'system',
        CURRENT_TIMESTAMP,
        CURRENT_TIMESTAMP),
       (13,
        4,
        '分拣：任务、称重与打印',
        '入口：分拣 → 分拣任务。任务可按分拣员、送货时间、线路和供应商筛选；称重录入已分拣数量，差异要选原因；打印用分拣小票，票面含仓库、分拣员与供应商来源。',
        '<p>入口：分拣 → 分拣任务。</p><ol><li>筛选任务：按分拣员、送货时间、线路、供应商来源收窄。</li><li>指派：任务 → 指派，只能指派给员工；供应商不登录系统，代分拣由员工代录。</li><li>录入：打开称重面板，逐行录实分数量，短缺或超量必须选原因。</li><li>打印：任务 → 打印，选分拣小票；票面含供应商来源，可直接交给供应商。</li><li>汇总：商品分拣汇总按规格看总量，不跨销售单位相加。</li></ol><p>常见卡点：任务完成后不能再改数量；赠品行不需要录入分拣结果。</p>',
        NULL,
        16,
        0,
        0,
        'system',
        CURRENT_TIMESTAMP,
        CURRENT_TIMESTAMP),
       (8,
        4,
        '客户建档与商品可见性',
        '入口：客户 → 客户档案。建档要选客户类型、结算方式、负责业务员；结算方式选「集团」时才会出现「允许子客户使用集团钱包」开关，默认关闭。商品可见性在客户详情的「商品可见性」里，可选全部在售或指定商品白名单。',
        '<p>入口：客户 → 客户档案。</p><ol><li>新建客户：填名称、客户类型、结算方式、负责业务员；业务员留空表示暂不分配。</li><li>商品可见性：客户详情 → 商品可见性，选「全部在售」或指定规格白名单。</li><li>集团结算：结算方式选「集团」并保存后，才会出现「允许子客户使用集团钱包」；打开后子客户在商城可直接扣集团钱包余额。</li><li>改派业务员：客户列表 → 更多 → 改派业务员，编辑页不改负责业务员。</li><li>推广二维码：客户列表 → 更多 → 推广二维码，可生成、撤销并查看扫码记录。</li></ol><p>常见卡点：客户状态不是「合作中」时不能下单；集团钱包授权只在集团主体上设置，子客户那边看不到集团余额。</p>',
        NULL,
        11,
        0,
        0,
        'system',
        CURRENT_TIMESTAMP,
        CURRENT_TIMESTAMP),
       (10,
        4,
        '销售订单：录单到确认',
        '入口：订单 → 销售订单。后台可快速录单或补单，提交后确认；改价用「批量核价」，实量用「录入实际数量」。订单状态为草稿、待确认、已确认、已取消四种。',
        '<p>入口：订单 → 销售订单。</p><ol><li>快速录单：选客户、加商品规格与数量，保存为草稿。</li><li>提交：草稿提交后进入待确认；补单请用「补单」并填原因。</li><li>确认：确认时核对赊欠额度与结算方式，集团共享结算还要看集团是否授权。</li><li>改价：详情 → 批量核价，改价需有定价查询权限。</li><li>实量：非标品确认前录入实际数量，不登记会被拒绝。</li><li>追溯：订单详情的操作日志记录每一步操作人与时间。</li></ol><p>常见卡点：客户不可见该规格时不能下单；库存预留是显式动作，确认订单不会自动占用库存。</p>',
        NULL,
        13,
        0,
        0,
        'system',
        CURRENT_TIMESTAMP,
        CURRENT_TIMESTAMP),
       (11,
        4,
        '采购：汇总、下单与收货',
        '入口：采购 → 采购需求 / 采购订单 / 采购收货。先按时间段汇总订单需求，再按供应商与采购员生成采购单；采购单可生成二维码分享给现场，收货支持多次实收与超收容差。',
        '<p>入口：采购 → 采购需求 / 采购订单 / 采购收货。</p><ol><li>汇总需求：选时间段与仓库，可选「计算库存」扣掉现有库存。</li><li>生成采购单：按供应商、采购员分组生成，草稿确认后提交。</li><li>分享到现场：采购单 → 更多 → 分享，生成二维码；采购员手机扫码可录入单价与实收重量。</li><li>收货：采购收货 → 新建，按实收填数量，确认后按设置直接入库或等仓库二次确认。</li><li>超收：超过容差会被拒绝，需先调容差或改数量。</li></ol><p>常见卡点：采购单提交后不能直接改行，需走编辑或改派；分享链接过期或撤销后扫码会提示失效。</p>',
        NULL,
        14,
        0,
        0,
        'system',
        CURRENT_TIMESTAMP,
        CURRENT_TIMESTAMP),
       (17,
        4,
        '微信小程序：下单与支付',
        '入口：商城小程序或 H5。登录后选品加购，结算时选配送地址与结算方式（账期/余额/货到付款），提交后可在订单页看进度，已确认订单可用余额支付。',
        '<p>入口：商城小程序或 H5。</p><ol><li>登录：手机号 + 密码，首次登录需改密码。</li><li>选品：首页/分类/搜索进商品详情，选规格加购。</li><li>结算：选收货地址与配送仓，选结算方式；余额支付金额由系统算，客户端不填金额。</li><li>下单：提交后生成订单，可在订单页看状态。</li><li>支付：已确认且结算方式为余额的订单可点支付；重复点击不会重复扣款。</li><li>汇总：订单页顶部「商品汇总」看一段时间内买过的规格与金额。</li></ol><p>常见卡点：客户不可见的规格不会出现在商城；余额不足时不能选余额支付。</p>',
        NULL,
        20,
        0,
        0,
        'system',
        CURRENT_TIMESTAMP,
        CURRENT_TIMESTAMP),
       (15,
        4,
        '财务：应收、收款与对账',
        '入口：财务 → 应收 / 收款 / 应付 / 账款抵扣；报表 → 销售、采购、利润。应收按签收的实际出库生成，账款抵扣是把已收款用于结清客户账单，撤销抵扣要留原因。',
        '<p>入口：财务 → 应收 / 收款 / 应付 / 账款抵扣；报表 → 销售 / 采购 / 利润。</p><ol><li>看应收：财务 → 应收，按客户与账期筛选，金额是扣减后金额。</li><li>登记收款：选客户与收款方式，金额可为部分。</li><li>账款抵扣：把已收款用于结清客户账单；抵扣错了走撤销抵扣并填原因。</li><li>应付：按供应商看应付，登记付款后，将这笔付款用于抵扣供应商账单。</li><li>对账：客户/供应商对账单可生成版本，生成后新增记录生成新版本，不改旧内容。</li></ol><p>常见卡点：抵扣超额会被拒；对账单生成后不能直接改，只能重新出账。</p>',
        NULL,
        18,
        0,
        0,
        'system',
        CURRENT_TIMESTAMP,
        CURRENT_TIMESTAMP);

INSERT INTO xsy_v2.t_mail_template (template_code,
                                    template_subject,
                                    template_content,
                                    template_type,
                                    disable_flag,
                                    update_time,
                                    create_time)
VALUES ('login_verification_code',
        '登录验证码',
        '<!DOCTYPE HTML>
<html>
<head>
  <title>登录提醒</title>
  <meta http-equiv="Content-Type" content="text/html; charset=UTF-8"/>
  <style>
      * {
          font-family: SimSun;
          /* 4号字体 */
          font-size: 18px;
          /* 22磅行间距 */
          line-height: 29px;
      }

      .main_font_size {
          font-size: 12.0pt;
      }

      .mainContent {
          line-height: 28px;
      }

      p {
          margin: 0 auto;
          text-align: justify;
      }
  </style>

</head>
<body>
<div>
  <div style="margin: 0px auto;width: 690px;">
    <div class="mainContent">
      <h1>验证码</h1>
      <p>请在验证页面输入此验证码</p>
      <p><b>${code}</b></p>
      <p>验证码将于此电子邮件发出 5 分钟后过期。</p>
      <p>如果你未曾提出此请求，可以忽略这封电子邮件。</p>
    </div>

  </div>
</div>
</body>
</html>',
        'freemarker',
        FALSE,
        CURRENT_TIMESTAMP,
        CURRENT_TIMESTAMP);

