VALUES (1,
        '超级管理员',
        'SUPER_ADMIN',
        'V2 基线内置角色（员工1同时具备 administrator_flag，权限判定不受角色影响）',
        CURRENT_TIMESTAMP,
        CURRENT_TIMESTAMP),
       (2,
        '销售',
        'SCM_SALES',
        '仅本人名下客户与订单；仓库与成本不可见。持者必须 administrator_flag=false',
        CURRENT_TIMESTAMP,
        CURRENT_TIMESTAMP),
       (4,
        '采购员',
        'SCM_PURCHASER',
        '仅本人作为负责人的采购单与需求；库存余额查询需另配 employee_warehouse_scope 授权行',
        CURRENT_TIMESTAMP,
        CURRENT_TIMESTAMP),
       (5,
        '采购主管',
        'SCM_PURCHASER_LEAD',
        '采购全部权限 + 采购归属分配权 + 全部采购范围（含未分配）',
        CURRENT_TIMESTAMP,
        CURRENT_TIMESTAMP),
       (6,
        '仓管员',
        'SCM_STOREKEEPER',
        '仓库维度按 employee_warehouse_scope 授权行收窄；默认不含采购价、avg_cost 与库存金额',
        CURRENT_TIMESTAMP,
        CURRENT_TIMESTAMP),
       (8,
        '配送调度',
        'SCM_DISPATCHER',
        '线路规划与全量候选订单；调度在工作范围内可见地址、电话与订单金额',
        CURRENT_TIMESTAMP,
        CURRENT_TIMESTAMP),
       (9,
        '司机',
        'SCM_DRIVER',
        '只看绑定到本人的司机档案所属线路；未绑定 employee_id 的司机档案取不到任何线路，金额默认隐藏',
        CURRENT_TIMESTAMP,
        CURRENT_TIMESTAMP),
       (10,
        '财务',
        'SCM_FINANCE',
        '报表与查询按授权范围生效：跨业务员/采购员范围与全部仓库范围都是显式授权，导出与页面同一套范围；成本列由 scm:report:cost:query 单独控制',
        CURRENT_TIMESTAMP,
        CURRENT_TIMESTAMP),
       (11,
        '分拣员',
        'SCM_SORTER',
        '只能处理派给自己的分拣任务，且任务所在仓必须在自己的授权仓内；不能建单、指派、取消或重开',
        CURRENT_TIMESTAMP,
        CURRENT_TIMESTAMP),
       (7,
        '仓库主管',
        'SCM_STOREKEEPER_LEAD',
        '仓管全部权限 + 成本字段可见 + 仓库授权行维护 + 全部仓库范围 + 分拣队列管理（建单 / 指派 / 取消 / 重开 / 汇总）',
        CURRENT_TIMESTAMP,
        CURRENT_TIMESTAMP),
       (3,
        '销售主管',
        'SCM_SALES_LEAD',
        '销售全部权限 + 客户归属分配权 + 全部客户/订单范围（含未分配）+ 退货/退款业务审批（不含资金操作）+ 商城未分配订单指派',
        CURRENT_TIMESTAMP,
        CURRENT_TIMESTAMP);

